package vn.xuannhashop.business.payroll.application;
import java.math.*;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import vn.xuannhashop.business.rules.*;
import vn.xuannhashop.business.shared.security.ActorContext;
import vn.xuannhashop.business.finance.application.FinanceApplication;
import vn.xuannhashop.business.shared.*;
import vn.xuannhashop.business.shared.audit.ActivityService;
@Service
public class PayrollService implements PayrollApplication {
    private final PayrollRepository r;private final ActorContext actor;private final Commands commands;private final ActivityService audit;private final FinanceApplication finance;private final RuleEngine engine;private final Map<String,PayrollRule> rules;
    public PayrollService(PayrollRepository r,ActorContext a,Commands c,ActivityService au,FinanceApplication f,RuleEngine e,Map<String,PayrollRule> rules){this.r=r;actor=a;commands=c;audit=au;finance=f;engine=e;this.rules=rules;}
    public Map<String,Object> overview(){actor.require("OWNER","HR","ACCOUNTANT");var staff=r.staff().stream().map(p->{var view=new LinkedHashMap<String,Object>(p);if(actor.current().role().equals("HR"))view.remove("hourly_rate");return view;}).toList();return Map.of("staff",staff,"work",r.work(),"payroll",actor.current().role().equals("HR")?List.of():r.payroll(),"policy","DEV-HOURLY-1: số giờ đã duyệt × đơn giá mẫu; cộng/trừ các khoản đã duyệt; tạm ứng trừ một lần. Chưa tự tính thuế/bảo hiểm.");}
    @Transactional public UUID work(UUID staff,LocalDate date,BigDecimal hours,String key){actor.require("OWNER","HR");if(date==null||date.isAfter(LocalDate.now())||hours==null||hours.signum()<=0||hours.compareTo(new BigDecimal("24"))>0||hours.scale()>2)throw DomainException.bad("Ngày công hoặc số giờ không hợp lệ.");return commands.once(key,"WORK:"+staff+":"+date+":"+hours,()->{if(r.lockStaff(staff)==null)throw DomainException.missing();if(r.periodLocked(staff,YearMonth.from(date).toString()))throw DomainException.conflict("Kỳ đã chốt dữ liệu lương; cần quy trình điều chỉnh.");var id=UUID.randomUUID();r.work(id,staff,date,hours,actor.username());audit.record("WORK_RECORDED",staff,date+" / "+hours);return id;});}
    @Transactional public void approveWork(UUID id,String key){actor.require("OWNER","ACCOUNTANT");commands.once(key,"WORK_APPROVE:"+id,()->{var w=r.lockWork(id);if(w==null)throw DomainException.missing();UUID staff=(UUID)w.get("staff_id");r.lockStaff(staff);if(w.get("approved_by")!=null||w.get("recorded_by").equals(actor.username()))throw DomainException.conflict("Người duyệt phải khác người lập; bản ghi chưa được duyệt.");if(r.periodLocked(staff,YearMonth.from((LocalDate)w.get("work_date")).toString()))throw DomainException.conflict("Kỳ lương đã chốt.");r.approveWork(id,actor.username());audit.record("WORK_APPROVED",id,"Duyệt công");return id;});}
    @Transactional public UUID draft(UUID staff,String period,String key){actor.require("OWNER","ACCOUNTANT");try{YearMonth.parse(period);}catch(Exception e){throw DomainException.bad("Kỳ lương có dạng YYYY-MM.");}return commands.once(key,"PAYROLL_DRAFT:"+staff+":"+period,()->{var p=r.lockStaff(staff);if(p==null)throw DomainException.missing();if(r.periodLocked(staff,period))throw DomainException.conflict("Bảng lương kỳ này đã tồn tại.");var hours=r.approvedHours(staff,period);if(r.pendingAdjustments(staff,period))throw DomainException.conflict("Còn khoản lương chờ duyệt trong kỳ.");var rate=(BigDecimal)p.get("hourly_rate");var amount=engine.select(rules,"payrollDEV1").calculate(hours,rate).add(r.adjustmentTotal(staff,period));if(amount.signum()<0||amount.compareTo(new BigDecimal("999999999999.99"))>0||(hours.signum()==0&&amount.signum()==0))throw DomainException.bad("Lương thực trả không hợp lệ; đối chiếu công, tạm ứng và khoản điều chỉnh.");var id=UUID.randomUUID();r.draft(id,staff,period,hours,rate,amount,actor.username());audit.record("PAYROLL_DRAFTED",id,period+" / DEV-HOURLY-1");return id;});}
    @Transactional public void approve(UUID id,String key){actor.require("OWNER","ACCOUNTANT");commands.once(key,"PAYROLL_APPROVE:"+id,()->{var p=r.lockPayroll(id);if(p==null)throw DomainException.missing();if(!p.get("status").equals("DRAFT")||p.get("prepared_by").equals(actor.username()))throw DomainException.conflict("Bảng lương phải ở dạng nháp và được người khác duyệt.");r.status(id,"APPROVED",actor.username());audit.record("PAYROLL_APPROVED",id,"Duyệt bảng lương");return id;});}
    @Transactional public void pay(UUID id,String key){actor.require("OWNER","ACCOUNTANT");commands.once(key,"PAYROLL_PAY:"+id,()->{var p=r.lockPayroll(id);if(p==null)throw DomainException.missing();if(!p.get("status").equals("APPROVED"))throw DomainException.conflict("Chỉ chi bảng lương đã duyệt và chưa trả.");if(((BigDecimal)p.get("amount")).signum()>0)finance.payPayroll(id,(BigDecimal)p.get("amount"),"payroll:"+id);else audit.record("PAYROLL_ZERO_SETTLED",id,"Đã đối chiếu công và tạm ứng, thực trả bằng 0");r.status(id,"PAID",actor.username());return id;});}
}
